func SeparateParenGroups(paren_string string) []string {
    groups := make([]string, 0)
    currentGroup := ""

    inGroup := false
    braceCount := 0

    for _, char := range paren_string {
        if char == '(' {
            inGroup = true
            braceCount++
            currentGroup += string(char)
        } else if char == ')' {
            braceCount--
            currentGroup += string(char)
            if braceCount == 0 {
                inGroup = false
                groups = append(groups, currentGroup)
                currentGroup = ""
            }
        } else if inGroup {
            currentGroup += string(char)
        }
    }

    return groups
}

