import (
	"fmt"
	"strings"
)

func SeparateParenGroups(paren_string string) []string {
	paren_string = strings.ReplaceAll(paren_string, " ", "")
	groups := make([]string, 0)
	currGroup := ""

	for _, char := range paren_string {
		if string(char) == "(" {
			currGroup += string(char)
		} else if string(char) == ")" {
			currGroup += string(char)
			groups = append(groups, currGroup)
			currGroup = ""
		}
	}

	return groups
}

func main() {
	result := SeparateParenGroups("( ) (( )) (( )( ))")
	fmt.Println(result)
}

