import (
	"strconv"
	"strings"
)

func TruncateNumber(number float64) float64 {
    strNum := strconv.FormatFloat(number, 'f', -1, 64)
    parts := strings.Split(strNum, ".")
    if len(parts) != 2 {
        return 0.0
    }
    decimalPart, _ := strconv.ParseFloat("0."+parts[1], 64)
    return decimalPart
}

