func Intersperse(numbers []int, delimeter int) []int {
    if len(numbers) <= 1 {
        return numbers
    }

    lastIndex := len(numbers) - 1
    for i := lastIndex; i > 0; i-- {
        numbers = append(numbers[:i], append([]int{delimeter}, numbers[i:]...)...)
    }

    return numbers
}

