func SumProduct(numbers []int) [2]int {
    if len(numbers) == 0 {
        return [2]int{0, 1}
    }

    min := numbers[0]
    max := numbers[0]

    for _, num := range numbers {
        if num < min {
            min = num
        }
        if num > max {
            max = num
        }
    }

    return [2]int{min + max, min * max}
}

