        if s[i] != s[len(s)-1-i] {
            return false
        }
    }
    return true
}

func MakePalindrome(str string) string {
    if len(str) == 0 {
        return ""
    }

    for i := len(str) - 1; i >= 0; i-- {
        if isPalindrome(str[:i+1]) {
            return str + strings.Join(reverseStr(str[:i]), "")
        }
    }

    return str + strings.Join(reverseStr(str), "")
}

