    strLen := len(str)

    subHash := 0
    strHash := 0
    base := 26
    prime := 31
    power := 1

    for i := 0; i < subLen; i++ {
        subHash = subHash*base + int(substring[i])
        strHash = strHash*base + int(str[i])
