    if len(substring) == 0 {
        return 0
    }

    count := 0
    hashSub := 0
    hashStr := 0
    prime := 101
    base := 256

    for i := 0; i < len(substring); i++ {
        hashSub = (hashSub*base + int(substring[i])) % prime
        hashStr = (hashStr*base + int(str[i])) % prime
    }

    for i := 0; i <= len(str)-len(substring); i++ {
        if hashStr == hashSub {
            match := true
            for j := 0; j < len(substring); j++ {
                if str[i+j] != substring[j] {
                    match = false
                    break
                }
            }
            if match {
                count++
            }
        }

        if i < len(str)-len(substring) {
            hashStr = (base*(hashStr-int(str[i])*int((base^(len(substring)-1)))%prime) + int(str[i+len(substring)])) % prime
            if hashStr < 0 {
                hashStr += prime
            }
        }
    }

    return count
}

