func FilterIntegers(values []interface{}) []int {
    if len(values) == 0 {
        return []int{}
    }

    res := make([]int, 0)
    index := 0

    for i := 0; i < len(values); i++ {
        if _, ok := values[i].(int); ok {
            res = append(res, values[i].(int))
            index++
        }
    }

    return res[:index]
}

