func RemoveDuplicates(numbers []int) []int {
    unique := []int{}

    for i := 0; i < len(numbers); i++ {
        isDuplicate := false
        for j := i + 1; j < len(numbers); j++ {
            if numbers[i] == numbers[j] {
                isDuplicate = true
                break
            }
        }
        if !isDuplicate {
            unique = append(unique, numbers[i])
        }
    }

    return unique
}

