func FindZero(xs []int) float64 {
	if len(xs) < 2 {
		return 0
	}

	a := float64(xs[0]) // Coefficient of x^3
	b := float64(xs[1]) // Coefficient of x^2
	c := float64(xs[2]) // Coefficient of x
	d := float64(xs[3]) // Constant term

	// Using Newton's method to find the zero point of the polynomial
	f := func(x float64) float64 {
		return a*x*x*x + b*x*x + c*x + d
	}

	fPrime := func(x float64) float64 {
		return 3*a*x*x + 2*b*x + c
	}

	// Initial guess
	x := 1.0

	// Newton's method iteration
	for i := 0; i < 1000; i++ {
		x = x - f(x)/fPrime(x)
	}

	return x
}

