	"sort"
)

func Unique(l []int) []int {
    uniqueList := make([]int, 0)

    for _, num := range l {
        found := false
        for _, uniqNum := range uniqueList {
            if uniqNum == num {
                found = true
                break
            }
        }
        if !found {
            uniqueList = append(uniqueList, num)
        }
    }

    sort.Ints(uniqueList)

    return uniqueList
}

