func PairsSumToZero(l []int) bool {
    if len(l) < 2 {
        return false
    }

    sort.Ints(l)

    left := 0
    right := len(l) - 1

    for left < right {
        sum := l[left] + l[right]
        if sum == 0 {
            return true
        } else if sum < 0 {
            left++
        } else {
            right--
        }
    }

    return false
}

