func BelowThreshold(l []int, t int) bool {
    sorted := make([]int, len(l))
    copy(sorted, l)
    for i := 1; i < len(sorted); i++ {
        if sorted[i-1] >= sorted[i] {
            sorted[i], sorted[i-1] = sorted[i-1], sorted[i]
            if i > 1 {
                i -= 2
            }
        }
    }
    return sorted[len(sorted)-1] < t
}

