func Fibfib(n int) int {
	if n == 0 || n == 1 {
		return 0
	} else if n == 2 {
		return 1
	}

	first, second, third := 0, 0, 1
	result := 0

	for i := 3; i <= n; i++ {
		result = first + second + third
		first, second, third = second, third, result
	}

	return result
}

