func CircularShift(x int, shift int) string {
    numStr := strconv.Itoa(x)
    numDigits := len(numStr)
    if shift > numDigits {
        return reverseString(numStr)
    }
    shiftedStr := make([]byte, numDigits)
    for i := 0; i < numDigits; i++ {
        shiftedStr[(i+shift)%numDigits] = numStr[i]
    }
    return string(shiftedStr)
}

func reverseString(s string) string {
    reversed := make([]byte, len(s))
    for i := 0; i < len(s); i++ {
        reversed[i] = s[len(s)-1-i]
    }
    return string(reversed)
}

