    for i, node := range arr {
        if node%2 == 0 {
            evenNodes = append(evenNodes, i)
        }
    }

    if len(evenNodes) == 0 {
        return []int{}
    }

    sort.SliceStable(evenNodes, func(i, j int) bool {
        if arr[evenNodes[i]] == arr[evenNodes[j]] {
            return evenNodes[i] < evenNodes[j]
        }
        return arr[evenNodes[i]] < arr[evenNodes[j]]
    })

    return []int{arr[evenNodes[0]], evenNodes[0]}
