import (
	"sort"
)

func SmallestChange(arr []int) int {
    sortedArr := make([]int, len(arr))
    copy(sortedArr, arr)
    sort.Ints(sortedArr)

    changes := 0
    left := 0
    right := len(arr) - 1

    for left < right {
        if arr[left] != sortedArr[left] {
            changes++
        }
        if arr[right] != sortedArr[right] {
            changes++
        }
        left++
        right--
    }

    if left == right && arr[left] != sortedArr[left] {
        changes++
    }

    return changes
}

