func DecimalToBinary(decimal int) string {
    if decimal == 0 {
        return "db0db"
    }

    binary := ""
    for decimal > 0 {
        remainder := decimal % 2
        binary = fmt.Sprintf("%d%s", remainder, binary)
        decimal = decimal / 2
    }

    return fmt.Sprintf("db%sdb", binary)
}

