    end := intPow(10, n)

    for i := start; i < end; i++ {
        nums = append(nums, i)
    }

    sort.Ints(nums)

    for _, num := range nums {
        if num%10 == 1 || num/intPow(10, n-1) == 1 {
            count++
        }
    }

    return count
}

func intPow(x, y int) int {
    return int(math.Pow(float64(x), float64(y)))
}

