func AntiShuffle(s string) string {
    var result string
    var wordStart int

    for i := 0; i < len(s); i++ {
        if s[i] == ' ' {
            result += string(sortWord(s[wordStart:i]))
            result += " "
            wordStart = i + 1
        }
    }

    result += string(sortWord(s[wordStart:]))

    return result
}

func sortWord(word string) []rune {
    wordRunes := []rune(word)
    for i := 0; i < len(wordRunes); i++ {
        for j := i + 1; j < len(wordRunes); j++ {
            if wordRunes[j] < wordRunes[i] {
                wordRunes[i], wordRunes[j] = wordRunes[j], wordRunes[i]
            }
        }
    }
    return wordRunes
}

