import (
	"math"
)

func NextSmallest(lst []int) interface{} {
	if len(lst) < 2 {
		return nil
	}

	min := lst[0]
	secondMin := math.MaxInt64

	for i := 1; i < len(lst); i++ {
		if lst[i] < min {
			secondMin = min
			min = lst[i]
		} else if lst[i] < secondMin && lst[i] != min {
			secondMin = lst[i]
		}
	}

	if secondMin == math.MaxInt64 {
		return nil
	}

	return secondMin
}

