        case 'o':
            encodedMessage += "q"
        case 'O':
            encodedMessage += "Q"
        case 'u':
            encodedMessage += "w"
        case 'U':
            encodedMessage += "W"
        default:
            if char >= 'a' && char <= 'z' {
                encodedMessage += strings.ToUpper(string(char))
            } else if char >= 'A' && char <= 'Z' {
                encodedMessage += strings.ToLower(string(char))
            }
        }
    }

    return encodedMessage
}

