func sortString(s string) string {
    sBytes := []byte(s)
    for i := 0; i < len(sBytes); i++ {
        for j := i + 1; j < len(sBytes); j++ {
            if sBytes[i] > sBytes[j] {
                sBytes[i], sBytes[j] = sBytes[j], sBytes[i]
            }
        }
    }
    return string(sBytes)
}

