import (
	"sort"
)

func hasEvenDigit(num int) bool {
	for num > 0 {
		digit := num % 10
		if digit%2 == 0 {
			return true
		}
		num /= 10
	}
	return false
}

func UniqueDigits(x []int) []int {
	resultMap := make(map[int]bool)

	for _, num := range x {
		if !hasEvenDigit(num) {
			resultMap[num] = true
		}
	}

	result := make([]int, 0, len(resultMap))
	for num := range resultMap {
		result = append(result, num)
	}

	sort.Ints(result)
	return result
}

