	"sort"
)

func UniqueDigits(x []int) []int {
    isOdd := func(num int) bool {
        for num > 0 {
            digit := num % 10
            if digit%2 == 0 {
                return false
            }
            num /= 10
        }
        return true
    }

    sort.Slice(x, func(i, j int) bool {
        return x[i] < x[j]
    })

    result := make([]int, 0)
    for _, num := range x {
        if isOdd(num) {
            result = append(result, num)
        }
    }

    return result
}

