import (
	"sort"
	"strconv"
)

func UniqueDigits(x []int) []int {
	var result []int

	for _, num := range x {
		hasEvenDigit := false
		strNum := strconv.Itoa(num)

		for _, char := range strNum {
			digit, _ := strconv.Atoi(string(char))
			if digit%2 == 0 {
				hasEvenDigit = true
				break
			}
		}

		if !hasEvenDigit {
			result = append(result, num)
		}
	}

	sort.Ints(result)

	return result
}

