func factorial(n int) int {
    if n == 0 {
        return 1
    }
    return n * factorial(n-1)
}

func sum(start, end int, hash map[int]int) int {
    if start > end {
        return 0
    }

    if val, ok := hash[end]; ok {
        return val
    }

    result := end + sum(start, end-1, hash)
    hash[end] = result
    return result
}

