func cacheFactorial(num int, cache map[int]int) int {
    if val, ok := cache[num]; ok {
        return val
    } else {
        result := num * cacheFactorial(num-1, cache)
        cache[num] = result
        return result
    }
}

func cacheSum(num int, cache map[int]int) int {
    if val, ok := cache[num]; ok {
        return val
    } else {
        result := num + cacheSum(num-1, cache)
        cache[num] = result
        return result
    }
}

