func Histogram(test string) map[rune]int {
    charCount := make(map[rune]int)

    var maxCount int
    var maxChars []rune

    chars := []rune(test)
    sort.Slice(chars, func(i, j int) bool {
        return chars[i] < chars[j]
    })

    for i := 0; i < len(chars); {
        count := 1
        j := i + 1
        for j < len(chars) && chars[i] == chars[j] {
            count++
            j++
        }

        if count > maxCount {
            maxCount = count
            maxChars = []rune{chars[i]}
        } else if count == maxCount {
            maxChars = append(maxChars, chars[i])
        }

        charCount[chars[i]] = count
        i = j
    }

    result := make(map[rune]int)
    for _, ch := range maxChars {
        result[ch] = charCount[ch]
    }

    return result
}

