func Minsubarraysum(nums []int) int {
    if len(nums) == 0 {
        return 0
    }

    minSum := math.MaxInt32

    for i := 0; i < len(nums); i++ {
        currSum := 0
        for j := i; j < len(nums); j++ {
            currSum += nums[j]
            if currSum < minSum {
                minSum = currSum
            }
        }
    }

    return minSum
}

