    selected := make([]int, k)
    for i := 0; i < k; i++ {
        selected[i] = arr[i]
    }

    for i := k; i < len(arr); i++ {
        minIdx := 0
        for j := 1; j < k; j++ {
            if selected[j] < selected[minIdx] {
                minIdx = j
            }
        }

        if arr[i] > selected[minIdx] {
            selected[minIdx] = arr[i]
        }
    }

    return selected
}

