func Maximum(arr []int, k int) []int {
	if k == 0 {
		return []int{}
	}

	maxHeap := make([]int, k)
	for i := 0; i < k; i++ {
		maxHeap[i] = arr[i]
	}

	for i := k/2 - 1; i >= 0; i-- {
		heapify(maxHeap, k, i)
	}

	for i := k; i < len(arr); i++ {
		if arr[i] > maxHeap[0] {
			maxHeap[0] = arr[i]
			heapify(maxHeap, k, 0)
		}
	}

	return maxHeap
}

func heapify(arr []int, n, i int) {
	largest := i
	left := 2*i + 1
	right := 2*i + 2

	if left < n && arr[left] > arr[largest] {
		largest = left
	}
	if right < n && arr[right] > arr[largest] {
		largest = right
	}

	if largest != i {
		arr[i], arr[largest] = arr[largest], arr[i]
		heapify(arr, n, largest)
	}
}

