import (
	"fmt"
	"math"
)

func isPrime(n int) bool {
	if n <= 1 {
		return false
	}
	if n == 2 {
		return true
	}
	if n%2 == 0 {
		return false
	}
	maxDivisor := int(math.Sqrt(float64(n)))
	for i := 3; i <= maxDivisor; i += 2 {
		if n%i == 0 {
			return false
		}
	}
	return true
}

func Intersection(interval1 [2]int, interval2 [2]int) string {
	start := interval1[0]
	end := interval1[1]
	if interval2[0] > start {
		start = interval2[0]
	}
	if interval2[1] < end {
		end = interval2[1]
	}
	if end < start {
		return "NO"
	}
	intersectionLength := end - start + 1
	if isPrime(intersectionLength) {
		return "YES"
	}
	return "NO"
}

func main() {
	fmt.Println(Intersection([2]int{1, 2}, [2]int{2, 3}))    // Output: "NO"
	fmt.Println(Intersection([2]int{-1, 1}, [2]int{0, 4}))    // Output: "NO"
	fmt.Println(Intersection([2]int{-3, -1}, [2]int{-5, 5}))  // Output: "YES"
}

