import (
	"fmt"
)

func isPrime(num int) bool {
	if num <= 1 {
		return false
	}
	for i := 2; i*i <= num; i++ {
		if num%i == 0 {
			return false
		}
	}
	return true
}

func Intersection(interval1 [2]int, interval2 [2]int) string {
	start1, end1 := interval1[0], interval1[1]
	start2, end2 := interval2[0], interval2[1]

	if end1 < start2 || end2 < start1 {
		return "NO"
	}

	intersectionStart := max(start1, start2)
	intersectionEnd := min(end1, end2)
	intersectionLength := intersectionEnd - intersectionStart + 1

	if isPrime(intersectionLength) {
		return "YES"
	} else {
		return "NO"
	}
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func main() {
	fmt.Println(Intersection([2]int{1, 2}, [2]int{2, 3}))    // "NO"
	fmt.Println(Intersection([2]int{-1, 1}, [2]int{0, 4}))    // "NO"
	fmt.Println(Intersection([2]int{-3, -1}, [2]int{-5, 5}))  // "YES"
}

