func Minpath(grid [][]int, k int) []int {
    n := len(grid)

    visited := make(map[int]bool)
    path := make([]int, 0, k)

    var dfs func(row, col int, steps int) bool
    dfs = func(row, col, steps int) bool {
        if row < 0 || row >= n || col < 0 || col >= n || visited[grid[row][col]] {
            return false
        }

        visited[grid[row][col]] = true
        path = append(path, grid[row][col])

        if steps == k {
            return true
        }

        if dfs(row+1, col, steps+1) || dfs(row-1, col, steps+1) || dfs(row, col+1, steps+1) || dfs(row, col-1, steps+1) {
            return true
        }

        path = path[:len(path)-1]
        visited[grid[row][col]] = false

        return false
    }

    for i := 0; i < n; i++ {
        for j := 0; j < n; j++ {
            if dfs(i, j, 1) {
                return path
            }
        }
    }

    return nil
}

