    idx := 0
    var path []int

    for i := 0; i < k; i++ {
        x, y := idx/n, idx%n
        path = append(path, grid[x][y])

        if (x+y)%2 == 0 {
            if y+1 < n {
                y++
            } else {
                x++
            }
        } else {
            if x+1 < n {
                x++
            } else {
                y++
            }
        }

        idx = x*n + y
