func Minpath(grid [][]int, k int) []int {
    n := len(grid)
    visited := make([][]bool, n)
    for i := range visited {
        visited[i] = make([]bool, n)
    }

    var findMinPath func(row, col, steps int, path []int) []int
    findMinPath = func(row, col, steps int, path []int) []int {
        if row < 0 || row >= n || col < 0 || col >= n || visited[row][col] || steps > k {
            return nil
        }

        visited[row][col] = true
        path = append(path, grid[row][col])

        if steps == k {
            return path
        }

        downPath := findMinPath(row+1, col, steps+1, append([]int{}, path...))
        rightPath := findMinPath(row, col+1, steps+1, append([]int{}, path...))
        upPath := findMinPath(row-1, col, steps+1, append([]int{}, path...))
        leftPath := findMinPath(row, col-1, steps+1, append([]int{}, path...))

        visited[row][col] = false

        minPath := path
        for _, p := range []struct {
            path []int
            valid bool
        }{downPath, rightPath, upPath, leftPath} {
            if p.path != nil && (minPath == nil || isSmallerPath(p.path, minPath)) {
                minPath = p.path
            }
        }

        return minPath
    }

    isSmallerPath := func(pathA, pathB []int) bool {
        for i := 0; i < k; i++ {
            if pathA[i] < pathB[i] {
                return true
            } else if pathA[i] > pathB[i] {
                return false
            }
        }
        return false
    }

    startPath := []int{grid[0][0]}
    return findMinPath(0, 0, 1, startPath)
}

