		visited[i][j] = true

		neighbors := [4][2]int{{i - 1, j}, {i + 1, j}, {i, j - 1}, {i, j + 1}}
		for _, neighbor := range neighbors {
			ni, nj := neighbor[0], neighbor[1]
			if ni >= 0 && ni < n && nj >= 0 && nj < n && !visited[ni][nj] {
				dfs(ni, nj, steps+1)
				break
			}
		}
	}

	dfs(0, 0, 0)
	return path
}

