func Minpath(grid [][]int, k int) []int {
    n := len(grid)
    visited := make(map[int]bool)
    path := make([]int, 0, k)

    var findMinPath func(x, y, steps int) bool
    findMinPath = func(x, y, steps int) bool {
        if steps == 0 {
            return true
        }
        key := x*n + y
        if visited[key] {
            return false
        }
        path = append(path, grid[x][y])
        visited[key] = true
        for dx := -1; dx <= 1; dx++ {
            for dy := -1; dy <= 1; dy++ {
                if dx != 0 && dy != 0 {
                    continue
                }
                nx, ny := x+dx, y+dy
                if nx >= 0 && nx < n && ny >= 0 && ny < n {
                    if findMinPath(nx, ny, steps-1) {
                        return true
                    }
                }
            }
        }
        visited[key] = false
        path = path[:len(path)-1]
        return false
    }

    for i := 0; i < n; i++ {
        for j := 0; j < n; j++ {
            if findMinPath(i, j, k-1) {
                return path
            }
        }
    }

    return nil
}

