func FileNameCheck(file_name string) string {
	validExtensions := map[string]bool{
		"txt": true,
		"exe": true,
		"dll": true,
	}

	dotIndex := strings.LastIndex(file_name, ".")
	if dotIndex == -1 || dotIndex == 0 || dotIndex == len(file_name)-1 {
		return "No"
	}

	if _, exists := validExtensions[file_name[dotIndex+1:]]; !exists {
		return "No"
	}

	digitsCount := 0
	for _, char := range file_name {
		if char >= '0' && char <= '9' {
