func OrderByPoints(nums []int) []int {
    if len(nums) == 0 {
        return nums
    }

    sumOfDigits := func(num int) int {
        sum := 0
        n := num
        for n != 0 {
            digit := n % 10
            if digit < 0 {
                digit = -digit
            }
            sum += digit
            n /= 10
        }
        return sum
    }

    sortedIndices := make([]int, len(nums))
    for i := range sortedIndices {
        sortedIndices[i] = i
    }

    sort.Slice(sortedIndices, func(i, j int) bool {
        sumI := sumOfDigits(nums[sortedIndices[i]])
        sumJ := sumOfDigits(nums[sortedIndices[j]])
        if sumI != sumJ {
            return sumI < sumJ
        }
        return sortedIndices[i] < sortedIndices[j]
    })

    sortedNums := make([]int, len(nums))
    for i, index := range sortedIndices {
        sortedNums[i] = nums[index]
    }

    return sortedNums
}

