import (
	"sort"
)

var planets = map[string]int{
	"Mercury": 1,
	"Venus":   2,
	"Earth":   3,
	"Mars":    4,
	"Jupiter": 5,
	"Saturn":  6,
	"Uranus":  7,
	"Neptune": 8,
}

func Bf(planet1, planet2 string) []string {
	if _, ok := planets[planet1]; !ok {
		return []string{}
	}
	if _, ok := planets[planet2]; !ok {
		return []string{}
	}

	var result []string
	start, end := planets[planet1], planets[planet2]
	if start > end {
		start, end = end, start
	}
	for planet, orbit := range planets {
		if orbit > start && orbit < end {
			result = append(result, planet)
		}
	}

	sort.Slice(result, func(i, j int) bool {
		return planets[result[i]] < planets[result[j]]
	})

	return result
}

