func StrongestExtension(class_name string, extensions []string) string {
    strongestExtension := extensions[0]
    maxStrength := calculateStrength(extensions[0])

    for _, ext := range extensions {
        strength := calculateStrength(ext)
        if strength > maxStrength {
            strongestExtension = ext
            maxStrength = strength
        }
    }

    return class_name + "." + strongestExtension
}

func calculateStrength(extension string) float64 {
    capCount, smCount := 0, 0
    for _, char := range extension {
        if 'A' <= char && char <= 'Z' {
            capCount++
        } else if 'a' <= char && char <= 'z' {
            smCount++
        }
    }

    return float64(capCount - smCount)
}

