func IntToMiniRoman(number int) string {
    romanSymbols := []struct {
        Value int
        Symbol string
    }{
        {1000, "m"},
        {900, "cm"},
        {500, "d"},
        {400, "cd"},
        {100, "c"},
        {90, "xc"},
        {50, "l"},
        {40, "xl"},
        {10, "x"},
        {9, "ix"},
        {5, "v"},
        {4, "iv"},
        {1, "i"},
    }

    result := ""
    for _, symbol := range romanSymbols {
        for number >= symbol.Value {
            result += symbol.Symbol
            number -= symbol.Value
        }
    }

    return strings.ToLower(result)
}

