func FindMax(words []string) string {
	var maxWord string
	maxUniqueChars := 0

	sort.Strings(words)

	for _, word := range words {
		uniqueChars := make(map[rune]bool)
		count := 0

		for _, char := range word {
			if !uniqueChars[char] {
				count++
				uniqueChars[char] = true
			}
		}

		if count > maxUniqueChars {
			maxUniqueChars = count
			maxWord = word
		}
	}

	return maxWord
