	var maxWord string
	maxUniqueChars := 0

	for _, word := range words {
		count := make([]int, 26)
		uniqueChars := 0

		for _, ch := range word {
			idx := ch - 'a'
			if count[idx] == 0 {
				uniqueChars++
			}
			count[idx]++
		}

		if uniqueChars > maxUniqueChars || (uniqueChars == maxUniqueChars && word < maxWord) {
			maxWord = word
			maxUniqueChars = uniqueChars
		}
	}

	return maxWord
}

