func intPow(x, y int) int {
	result := 1

	for i := 0; i < y; i++ {
		result *= x
	}

	return result
}

func main() {
	operators := []string{"+", "*", "-"}
	operands := []int{2, 3, 4, 5}

	result := DoAlgebra(operators, operands)
	fmt.Println(result) // Output: 9
}

