import (
	"math"
)

func DoAlgebra(operator []string, operand []int) int {
    precedence := map[string]int{"+": 1, "-": 1, "*": 2, "//": 2, "**": 3}
    stackOperand := []int{}
    stackOperator := []string{}

    for i, op := range operator {
        for len(stackOperator) > 0 && precedence[op] <= precedence[stackOperator[len(stackOperator)-1]] {
            lastOp := stackOperator[len(stackOperator)-1]
            stackOperator = stackOperator[:len(stackOperator)-1]

            if lastOp == "+" {
                stackOperand[len(stackOperand)-2] += stackOperand[len(stackOperand)-1]
            } else if lastOp == "-" {
                stackOperand[len(stackOperand)-2] -= stackOperand[len(stackOperand)-1]
            } else if lastOp == "*" {
                stackOperand[len(stackOperand)-2] *= stackOperand[len(stackOperand)-1]
            } else if lastOp == "//" {
                stackOperand[len(stackOperand)-2] /= stackOperand[len(stackOperand)-1]
            } else if lastOp == "**" {
                stackOperand[len(stackOperand)-2] = int(math.Pow(float64(stackOperand[len(stackOperand)-2]), float64(stackOperand[len(stackOperand)-1])))
            }
            stackOperand = stackOperand[:len(stackOperand)-1]
        }

        stackOperand = append(stackOperand, operand[i])
        stackOperator = append(stackOperator, op)
    }

    for len(stackOperator) > 0 {
        lastOp := stackOperator[len(stackOperator)-1]
        stackOperator = stackOperator[:len(stackOperator)-1]

        if lastOp == "+" {
            stackOperand[len(stackOperand)-2] += stackOperand[len(stackOperand)-1]
        } else if lastOp == "-" {
            stackOperand[len(stackOperand)-2] -= stackOperand[len(stackOperand)-1]
        } else if lastOp == "*" {
            stackOperand[len(stackOperand)-2] *= stackOperand[len(stackOperand)-1]
        } else if lastOp == "//" {
            stackOperand[len(stackOperand)-2] /= stackOperand[len(stackOperand)-1]
        } else if lastOp == "**" {
            stackOperand[len(stackOperand)-2] = int(math.Pow(float64(stackOperand[len(stackOperand)-2]), float64(stackOperand[len(stackOperand)-1])))
        }
        stackOperand = stackOperand[:len(stackOperand)-1]
    }

    return stackOperand[0]
}

