func GenerateIntegers(a, b int) []int {
	var result []int

	if a > b {
		a, b = b, a
	}

	for i := a; i <= b; i++ {
		if i%2 == 0 {
			result = append(result, i)
		}
	}

	sort.Ints(result)

	return result
}

